"""Read-only synthetic SESSION-001 characterization from an explicit Git export."""
import asyncio
from dataclasses import asdict
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys


async def capture(source, revision):
    root = Path.cwd().resolve()
    env = dict(os.environ, GIT_OPTIONAL_LOCKS='0')
    git = lambda *a: subprocess.check_output(['git', '-C', str(root), *a], env=env)
    revision = git('rev-parse', '--verify', revision + '^{commit}').decode().strip()
    expected = {}
    for line in git('ls-tree', '-r', revision, '--', 'packages').decode().splitlines():
        header, name = line.split('\t', 1)
        if '/src/' in name:
            expected[name] = header.split()[2]
    actual = {str(f.relative_to(source)): f for tree in (source / 'packages').glob('*/src') for f in tree.rglob('*') if f.is_file()}
    if set(actual) != set(expected):
        raise RuntimeError('Source inventory differs from Git')
    for name, blob in expected.items():
        if actual[name].read_bytes() != git('cat-file', 'blob', blob):
            raise RuntimeError('Source byte drift: ' + name)
    roots = [f.resolve() for f in sorted((source / 'packages').glob('*/src'))]
    sys.path[:0] = [str(f) for f in roots]
    from friday_chat.commands.contracts import CommandContext, CommandMetadata
    from friday_chat.commands.registry import CommandRegistry, _clear_handler, _history_handler, build_default_registry

    rows = []
    marker = CommandMetadata('unused', 'Unused', 'unused', '/unused')

    class History(list):
        def __init__(self, values, events, failure=None):
            super().__init__(values)
            self.events = events
            self.failure = failure

        def clear(self):
            self.events.append('history.clear')
            if self.failure is not None:
                raise self.failure
            super().clear()

    class Context:
        def __init__(self, history, events, runtime=None, runtime_failure=None):
            self.history = history
            self.events = events
            self._runtime = runtime
            self.runtime_failure = runtime_failure
            self.exit_requested = False

        @property
        def runtime(self):
            self.events.append('runtime.read')
            if self.runtime_failure is not None:
                raise self.runtime_failure
            return self._runtime

    class Memory:
        def __init__(self, history, events, returned=True, failure=None):
            self.history, self.events, self.returned, self.failure = history, events, returned, failure

        async def clear_session_memory(self):
            self.events.append('memory.clear:history=' + json.dumps(self.history))
            if self.failure is not None:
                raise self.failure
            return self.returned

    class Runtime:
        def __init__(self, memory):
            self.memory = memory

    def result(value):
        data = asdict(value)
        data['ui_effects'] = [effect.value for effect in value.ui_effects]
        return data

    for label, turns in [('empty', []), ('one', [('hello', 'world')]), ('ordered', [('second', 'B'), ('first', 'A')]), ('unicode-newlines', [('Å\nuser', '答\nreply')]), ('formatted-values', [(False, None), (7, ['x'])]), ('malformed-short', [('only-one',)]), ('malformed-long', [('a', 'b', 'c')])]:
        events = []
        history = History(turns, events)
        context = Context(history, events, runtime_failure=RuntimeError('history touched runtime'))
        row = {'case': 'history:' + label, 'turns': turns, 'args': ['ignored', '"quoted"']}
        try:
            row['result'] = result(await _history_handler(context, tuple(row['args']), marker))
        except Exception as error:
            row['exception'] = {'type': type(error).__name__, 'message': str(error)}
        row['events'], row['history_after'] = events, list(history)
        rows.append(row)

    for label in ['no-runtime', 'memory-true', 'memory-false', 'memory-exception', 'memory-cancel', 'history-exception', 'runtime-exception']:
        events = []
        failure = asyncio.CancelledError('cancelled') if label == 'memory-cancel' else RuntimeError(label)
        history = History([('hello', 'world')], events, failure if label == 'history-exception' else None)
        memory = Memory(history, events, returned=label != 'memory-false', failure=failure if label in ('memory-exception', 'memory-cancel') else None)
